import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"ERB 的语句","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ERB_Statements.md","filePath":"reference/ERB_Statements.md"}`),a={name:`reference/ERB_Statements.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="erb-的语句" tabindex="-1">ERB 的语句 <a class="header-anchor" href="#erb-的语句" aria-label="Permalink to “ERB 的语句”">​</a></h1><p><strong>语句</strong>是脚本里的一个处理单位。EraBasic 遵循“一行一句”，除特殊行外，每一行就是一条语句。本页介绍<strong>简单语句</strong>（不能再拆出下级结构）；需要控制多行的结构见<a href="./ERB_Compound_Statements.html">复合语句</a>。</p><h2 id="语句的种类" tabindex="-1">语句的种类 <a class="header-anchor" href="#语句的种类" aria-label="Permalink to “语句的种类”">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td>赋值语句</td><td>把值装进变量</td><td><code>A = 10</code></td></tr><tr><td>命令语句</td><td>让引擎做事</td><td><code>PRINTL Hello</code></td></tr><tr><td>跳转语句</td><td>改变执行位置</td><td><code>GOTO Label</code></td></tr><tr><td>单行条件语句</td><td>条件成立才执行下一行</td><td><code>SIF A &gt; 0</code></td></tr><tr><td>注释</td><td>不执行，供人阅读</td><td><code>; 说明</code></td></tr></tbody></table><h2 id="赋值语句" tabindex="-1">赋值语句 <a class="header-anchor" href="#赋值语句" aria-label="Permalink to “赋值语句”">​</a></h2><p>把右边的值装进左边的变量：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 10</span></span>
<span class="line"><span style="color:#9CDCFE;">S</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;文本&quot;</span></span>
<span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> A</span><span style="color:#D4D4D4;"> +</span><span style="color:#B5CEA8;"> 1</span><span style="color:#6A9955;">        ; 先算右边，再存回左边</span></span>
<span class="line"><span style="color:#9CDCFE;">CFLAG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">5</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 100</span><span style="color:#6A9955;">  ; 也可以给数组元素赋值</span></span></code></pre></div><p>赋值号左右两边的<strong>类型必须一致</strong>：数值变量只能装数值，字符串变量只能装字符串。</p><p>复合赋值是简写：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> +=</span><span style="color:#B5CEA8;"> 1</span><span style="color:#6A9955;">   ; 等价于 A = A + 1</span></span>
<span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> -=</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> *=</span><span style="color:#B5CEA8;"> 2</span></span>
<span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> /=</span><span style="color:#B5CEA8;"> 2</span></span>
<span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> %=</span><span style="color:#B5CEA8;"> 2</span></span></code></pre></div><p>字符串用 <code>&#39;=</code> 进行赋值：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">S</span><span style="color:#D4D4D4;"> &#39;=</span><span style="color:#CE9178;"> &quot;文本&quot;</span><span style="color:#D4D4D4;"> +</span><span style="color:#DCDCAA;"> TOSTR</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">A</span><span style="color:#E6E6E6;">)</span></span></code></pre></div><h2 id="命令语句" tabindex="-1">命令语句 <a class="header-anchor" href="#命令语句" aria-label="Permalink to “命令语句”">​</a></h2><p>命令是引擎提供的操作，后跟参数：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">PRINTL</span><span style="color:#9CDCFE;"> Hello</span></span>
<span class="line"><span style="color:#569CD6;">INPUT</span></span>
<span class="line"><span style="color:#569CD6;">QUIT</span></span></code></pre></div><p>参数的具体格式由命令决定，完整的参数类型见<a href="./../translation/Command.html#值类型规范">值类型规范</a>。</p><h2 id="单行条件语句-sif" tabindex="-1">单行条件语句：SIF <a class="header-anchor" href="#单行条件语句-sif" aria-label="Permalink to “单行条件语句：SIF”">​</a></h2><p><code>SIF</code> 只在条件成立时执行<strong>下一行</strong>：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">SIF</span><span style="color:#9CDCFE;"> A</span><span style="color:#D4D4D4;"> &gt;</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> A</span><span style="color:#9CDCFE;"> 是正数</span></span></code></pre></div><p>它等价于：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">IF</span><span style="color:#9CDCFE;"> A</span><span style="color:#D4D4D4;"> &gt;</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> A</span><span style="color:#9CDCFE;"> 是正数</span></span>
<span class="line"><span style="color:#C586C0;">ENDIF</span></span></code></pre></div><blockquote><p><code>SIF</code> 的下一行不能是空行、注释行或标签行，否则会出错或失去意义。</p></blockquote><h2 id="跳转语句" tabindex="-1">跳转语句 <a class="header-anchor" href="#跳转语句" aria-label="Permalink to “跳转语句”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">GOTO</span><span style="color:#9CDCFE;"> 标签名</span></span></code></pre></div><p>跳转目标是<strong>标签</strong>（<code>$名称</code>）或<strong>函数</strong>（<code>@名称</code>）。另外：</p><ul><li><code>JUMP 函数名</code>：跳到函数，且不返回；</li><li><code>CALL 函数名</code>：调用函数，执行完返回；</li><li><code>RETURN</code>：从当前函数返回。</li></ul><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to “注释”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">; 整行注释</span></span>
<span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 10</span><span style="color:#6A9955;">  ; 行末注释</span></span></code></pre></div><table tabindex="0"><thead><tr><th>写法</th><th>说明</th></tr></thead><tbody><tr><td><code>;</code></td><td>普通注释</td></tr><tr><td><code>;!;</code></td><td>在 Emuera 中有效，在 Eramaker 中被视为注释</td></tr><tr><td><code>;#;</code></td><td>只在调试模式下执行</td></tr></tbody></table><h2 id="变量声明-预处理指令" tabindex="-1">变量声明（预处理指令） <a class="header-anchor" href="#变量声明-预处理指令" aria-label="Permalink to “变量声明（预处理指令）”">​</a></h2><p>变量不是“语句”，而是通过 <code>#</code> 开头的预处理指令声明：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> A</span><span style="color:#6A9955;">          ; 数值变量</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIMS</span><span style="color:#9CDCFE;"> S</span><span style="color:#6A9955;">         ; 字符串变量</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> FLAG</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">100</span><span style="color:#6A9955;">  ; 100 个元素的数值数组</span></span></code></pre></div><p>这些声明必须紧跟在函数定义之下，详见<a href="./../translation/Function_and_Preprocessor.html">函数与预处理指令</a>。</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./../guide/tutorials/Statement.html">简单语句</a>（教程）</li><li><a href="./ERB_Compound_Statements.html">复合语句</a></li><li><a href="./ERB_Expressions.html">ERB 的表达式</a></li><li><a href="./ERB_Commands.html">ERB 的命令</a></li></ul>`,35)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};